	set nmSp = %session.Data("NmSp")
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("In CreateRS, namespace: " _ nmSp)
    Set tRS = ""
    Set tSC = $$$OK
    set usrNm = $get(%session.Data("UsNm"))
    set sql = "SELECT FileName, InternalName, ClassModifiedTime, CompileUser, FileModifiedTime, CheckinUser, VersionNumber "
    _ " FROM IHC_ITF_SrcCtrlPkg.ClassInfo " 

 	if (nmSp '= "")
 	{
  		Set sql = sql _ " WHERE ( Namespace = '" _ nmSp _ "'"
 	}
 	else
 	{
	 	Quit null
 	}


 	Set incVal = $get(%session.Data("IncAllSvn"))
 	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("IncAllSvn  " _ incVal)
 	if (incVal = "1")
 	{
	 	Set sql = sql _ " OR Namespace IS NULL"
 	}
 	Set sql = sql _ ")"

	if ( ($get(%session.Data("IncClasses")) = 1) && ($get(%session.Data("IncOthers")) = 1) )
    {
    	Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetOtherFiles(%session.Data("NmSp"))
    }
    elseif ($get(%session.Data("IncClasses")) = 1)
    {
	    Set sql = sql _ " AND ( (InternalName like '%CLS') OR (InternalName like '%cls') "
	    if (incVal = "1")
 		{ 
 			Set sql = sql _ "OR (InternalName IS NULL) )"
 		}
 		else
 		{
	 		Set sql = sql _ ")"
 		}
    }
    elseif ($get(%session.Data("IncOthers")) = 1)
    {
       	Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetOtherFiles(%session.Data("NmSp"))

	    Set sql = sql _ " AND ( (InternalName not like '%CLS') "
	    if (incVal = "1")
 		{ 
 			Set sql = sql _ "OR (InternalName IS NULL) )"
 		}
 		else
 		{
	 		Set sql = sql _ ")"
 		}
    }
    else
 	{
	 	Quit null
 	}

   // Build WHERE clause based on filters
   set filterStr = $GET(pInfo.filters("FileName"))
    If (filterStr'="") {
        Set sql = sql _ " AND FileName [  '" _ filterStr _ "'"        
    }

 	Set tRS = ##class(%Library.ResultSet).%New()
    If $IsObject(tRS) {
    	Set tSC = tRS.Prepare(sql)
    	Set pInfo.queryText = sql

    	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(sql _ ", stat: " _ tSC _" INC: " _ incVal)
    }

   Quit tRS

