set rows = 1

try
{
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Start  GetSVNItems")	
Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CreateListOfFilesInSvn( $get(%session.Data("UsNm")), $get(%session.Data("PsWd")))
Do ..UpdateTime()
} catch err
{
	set errStr = "Exception in GetSVNItems: " _ err.Data _ " " _ err.Name _ " " _ err.Location
	&js<alert('Exception in GetSVNItems');>
