}
Quit rows

 set val = %query(pName) 	
 if ( $F(val, "LOOKUP") > 0)
 { 
	Write "<FONT COLOR=""BLUE"">" _ val _ "</FONT>"
 } 
 Elseif ( $F(val, "SYSDEF") > 0)
 { 
	Write "<FONT COLOR=""GREEN"">" _ val _ "</FONT>"
 } 
 else 
 { 
	Write val 
 } 

 Quit $$$OK


 If %query(pName) 
 { 


   set val = $GET(%query("ClassModifiedTime"))

   set srcVal = %query(pName)


   if (srcVal '= "")
   { 
      Set fileTime=$ZDATETIMEH(srcVal, 3, 1)

   }



   if (val = "")
   {
	   set srcVal = "<B> " _ srcVal _ " </B>"
	   Write srcVal
	   Quit $$$OK
   }
   else
   {
     Set intTime=$ZDATETIMEH(val, 3, 1)
   }



  // if date is greater OR date is same and time is greater
  if ( 
       ($p(intTime, ",", 1) > $p(fileTime, ",", 1)) || 
       (
         ($p(intTime, ",", 1) = $p(fileTime, ",", 1)) && ($p(intTime, ",", 2) > $p(fileTime, ",", 2))
       )
    )
   {	   
	   set srcVal = "<B><I><FONT COLOR=""RED"">" _ srcVal _ "</FONT></I></B>"
   }
   elseif(srcVal = "")
   {

    set srcVal = "<B><I> <FONT COLOR=""RED""> Not in SubVersion </FONT> </I></B>"

   }

   Write srcVal

 }
 else // %query
 {
	Write "<B><I> Not in SubVersion </I></B>"
 }
 Quit $$$OK

